func TestInterRegionCellClaimStartsFromTheBrokersClaim(t *testing.T) {
	material, directory, cfg, now := interRegionFixture(t)
	read := func(name string) []byte {
		t.Helper()
		body, err := os.ReadFile(filepath.Join(material, name))
		if err != nil {
			t.Fatal(err)
		}
