func build(cfg Config, now time.Time) (map[string][]byte, Public, error) {
	files := make(map[string][]byte)
	expires := now.Add(time.Duration(cfg.ValidityHours) * time.Hour)
	op, err := nkeys.CreateOperator()
	if err != nil {
		return nil, Public{}, err
	}
	defer op.Wipe()
	sys, err := nkeys.CreateAccount()
	if err != nil {
		return nil, Public{}, err
	}
	defer sys.Wipe()
	cell, err := nkeys.CreateAccount()
	if err != nil {
		return nil, Public{}, err
	}
	defer cell.Wipe()
	opID, _ := op.PublicKey()
	sysID, _ := sys.PublicKey()
	cellID, _ := cell.PublicKey()
	hostIssuer, err := nkeys.CreateAccount()
	if err != nil {
		return nil, Public{}, err
	}
	defer hostIssuer.Wipe()
	hostIssuerID, err := hostIssuer.PublicKey()
	if err != nil {
		return nil, Public{}, err
	}
	hostIssuerSeed, err := hostIssuer.Seed()
	if err != nil {
		return nil, Public{}, err
	}
	files["host-nats-issuer.seed"] = bytes.Clone(hostIssuerSeed)
	controllerSigner, err := nkeys.CreateAccount()
	if err != nil {
		return nil, Public{}, err
	}
	defer controllerSigner.Wipe()
	controllerSignerID, err := controllerSigner.PublicKey()
	if err != nil {
		return nil, Public{}, err
	}
	controllerSignerSeed, err := controllerSigner.Seed()
	if err != nil {
		return nil, Public{}, err
	}
	files["controller-account-signer.seed"] = bytes.Clone(controllerSignerSeed)
	for name, pair := range map[string]nkeys.KeyPair{"issuer-operator.seed": op, "issuer-system.seed": sys, "issuer-cell.seed": cell} {
		seed, err := pair.Seed()
		if err != nil {
			return nil, Public{}, err
		}
		files[name] = bytes.Clone(seed)
	}
	opClaim := jwt.NewOperatorClaims(opID)
	opClaim.SystemAccount = sysID
	opClaim.IssuedAt, opClaim.Expires = now.Unix(), expires.Unix()
	opJWT, err := opClaim.Encode(op)
	if err != nil {
		return nil, Public{}, err
	}
	sysClaim := jwt.NewAccountClaims(sysID)
	sysClaim.IssuedAt, sysClaim.Expires = now.Unix(), expires.Unix()
	sysJWT, err := sysClaim.Encode(op)
	if err != nil {
		return nil, Public{}, err
	}
	cellClaim := jwt.NewAccountClaims(cellID)
	cellClaim.IssuedAt, cellClaim.Expires = now.Unix(), expires.Unix()
	// Operator mode enables JetStream only for accounts whose JWT carries
	// JetStream limits. The server-wide store limit still bounds the cell.
	cellClaim.Limits.JetStreamLimits = jwt.JetStreamLimits{MemoryStorage: jwt.NoLimit, DiskStorage: jwt.NoLimit,
		Streams: jwt.NoLimit, Consumer: jwt.NoLimit}
	hostScope := expectedHostScope(cfg.Cell, hostIssuerID)
	cellClaim.SigningKeys.AddScopedSigner(hostScope)
	// The role signer (TS-651) from the start, so a new cell's roles get
	// NATS identities without a role-claim and broker-claim-apply.
	role, err := roleScope(hostIssuer)
	if err != nil {
		return nil, Public{}, err
	}
	cellClaim.SigningKeys.AddScopedSigner(role)
	cellClaim.SigningKeys.Add(controllerSignerID)
	if cfg.LinkSigner != "" {
		natscell.ApplyLink(cellClaim, cfg.LinkSigner)
	}
	cellJWT, err := cellClaim.Encode(op)
	if err != nil {
		return nil, Public{}, err
	}
	files["operator.jwt"], files["system.jwt"], files["cell.jwt"] = []byte(opJWT), []byte(sysJWT), []byte(cellJWT)
	systemUser, err := nkeys.CreateUser()
	if err != nil {
		return nil, Public{}, err
	}
	defer systemUser.Wipe()
	systemID, _ := systemUser.PublicKey()
	systemClaim := jwt.NewUserClaims(systemID)
	systemClaim.IssuerAccount = sysID
	systemClaim.IssuedAt, systemClaim.Expires = now.Unix(), expires.Unix()
	systemClaim.Pub.Allow = jwt.StringList{"$SYS.REQ.ACCOUNT." + cellID + ".CLAIMS.UPDATE"}
	systemClaim.Sub.Allow = jwt.StringList{inbox(cfg.Cell, systemID)}
	files["system.creds"], err = credentials(systemClaim, sys, systemUser)
	if err != nil {
		return nil, Public{}, err
	}
	operatorUser, err := nkeys.CreateUser()
	if err != nil {
		return nil, Public{}, err
	}
	defer operatorUser.Wipe()
	operatorID, err := operatorUser.PublicKey()
	if err != nil {
		return nil, Public{}, err
	}
	operatorClaim := jwt.NewUserClaims(operatorID)
	operatorClaim.IssuerAccount = cellID
	operatorClaim.IssuedAt, operatorClaim.Expires = now.Unix(), expires.Unix()
	operatorClaim.Pub.Allow = natscell.BrokerOperatorPublishPermissions(cfg.Cell)
	operatorClaim.Sub.Allow = jwt.StringList{inbox(cfg.Cell, operatorID)}
	files["operator.creds"], err = credentials(operatorClaim, cell, operatorUser)
	if err != nil {
		return nil, Public{}, err
	}
	caPEM, caKey, ca, err := makeCA(cfg, now, expires)
	if err != nil {
		return nil, Public{}, err
	}
	files["ca.pem"] = caPEM
	caDER, err := x509.MarshalECPrivateKey(caKey)
	if err != nil {
		return nil, Public{}, err
	}
	files["issuer-ca.key"] = pem.EncodeToMemory(&pem.Block{Type: "EC PRIVATE KEY", Bytes: caDER})
	hostCAPEM, hostCAKeyPEM, err := makeHostIssuerCA(cfg, now, expires, ca, caKey)
	if err != nil {
		return nil, Public{}, err
	}
	files["host-tls-issuer-cert.pem"] = hostCAPEM
	files["host-tls-issuer-key.pem"] = hostCAKeyPEM
	files["controller-tls-issuer-cert.pem"], files["controller-tls-issuer-key.pem"], err = makeControllerIssuerCA(cfg, now, minTime(expires, now.Add(controllerIssuedLifetime)), ca, caKey)
	if err != nil {
		return nil, Public{}, err
	}
	// Every controller holds the cell's C# TerraBase member CA and signs
	// member certificates with it; database hosts never see the key.
	memberCell, err := naming.RegionCell(strings.ToUpper(cfg.Cell)).Name()
	if err != nil {
		return nil, Public{}, err
	}
	files["terrabase-member-ca.pem"], files["terrabase-member-ca.key"], err = terrabase.NewCA(memberCell, now)
	if err != nil {
		return nil, Public{}, err
	}
	operatorCert, operatorKey, err := makeOperatorLeaf(cfg, now, expires, ca, caKey)
	if err != nil {
		return nil, Public{}, err
	}
	files["operator-tls-cert.pem"], files["operator-tls-key.pem"] = operatorCert, operatorKey
	password := make([]byte, 32)
	if _, err := rand.Read(password); err != nil {
		return nil, Public{}, err
	}
	files["route-password"] = []byte(base64.RawURLEncoding.EncodeToString(password) + "\n")
	clear(password)
	ticketPub, ticketKey, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		return nil, Public{}, err
	}
	ticketPub = bytes.Clone(ticketPub)
	files["ticket.pub"] = []byte(base64.StdEncoding.EncodeToString(ticketPub) + "\n")
	files["ticket.key"] = []byte(base64.StdEncoding.EncodeToString(ticketKey) + "\n")
	clear(ticketKey)
	peerPub, peerKey, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		return nil, Public{}, err
	}
	ledgerPub, ledgerKey, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		return nil, Public{}, err
	}
	peerPub, ledgerPub = bytes.Clone(peerPub), bytes.Clone(ledgerPub)
	files["founder-peer.key"], files["founder-ledger.key"] = bytes.Clone(peerKey), bytes.Clone(ledgerKey)
	clear(peerKey)
	clear(ledgerKey)
	responsePub, responseKey, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		return nil, Public{}, err
	}
	responsePublic := base64.StdEncoding.EncodeToString(responsePub)
	responseWire := []byte(base64.StdEncoding.EncodeToString(responseKey) + "\n")
	clear(responseKey)
	defer clear(responseWire)
	for _, slot := range cfg.Slots {
		user, err := nkeys.CreateUser()
		if err != nil {
			return nil, Public{}, err
		}
		userID, _ := user.PublicKey()
		claim := jwt.NewUserClaims(userID)
		claim.IssuerAccount = cellID
		claim.IssuedAt, claim.Expires = now.Unix(), expires.Unix()
		claim.Pub.Allow = natscell.ControllerPublishes(cfg.Cell)
		// Fresh material has no link topology: the standalone cell is its own home.
		claim.Pub.Allow.Add(natscell.GlobalControllerPublishes()...)
		claim.Pub.Allow.Add(natscell.GlobalControllerRequests()...)
		claim.Sub.Allow = jwt.StringList{inbox(cfg.Cell, userID), protocol.Broker(cfg.Cell, "ticket", ">"), protocol.Broker(cfg.Cell, "fence", slot.Name)}
		claim.Sub.Allow = append(claim.Sub.Allow, natscell.ControllerSubscriptions(cfg.Cell)...)
		claim.Sub.Allow.Add(natscell.GlobalControllerRequests()...)
		claim.Sub.Allow.Add(protocol.ObservabilityGrant(cfg.Cell))
		claim.Resp = &jwt.ResponsePermission{MaxMsgs: 1, Expires: 5 * time.Second}
		files[slot.Name+".creds"], err = credentials(claim, cell, user)
		user.Wipe()
		if err != nil {
			return nil, Public{}, err
		}
		cert, key, err := makeLeaf(cfg, slot, now, expires, ca, caKey)
		if err != nil {
			return nil, Public{}, err
		}
		files[slot.Name+"-tls-cert.pem"], files[slot.Name+"-tls-key.pem"] = cert, key
		files[slot.Name+"-response.key"] = bytes.Clone(responseWire)
	}
	public := Public{PeerSignerPublicKey: base64.StdEncoding.EncodeToString(peerPub), LedgerSignerPublicKey: base64.StdEncoding.EncodeToString(ledgerPub),
		TicketSignerPublicKey: base64.StdEncoding.EncodeToString(ticketPub), ControllerResponsePublicKey: responsePublic,
		HostNATSIssuerNKey: hostIssuerID, ControllerAccountSignerNKey: controllerSignerID, OperatorNKey: opID, SystemAccountNKey: sysID, CellAccountNKey: cellID}
	return files, public, nil
}

func ValidateLive(directory string, record Record) error {
	if _, err := Load(directory); err != nil {
		return err
	}
	if err := validateSignerFiles(directory, record); err != nil {
		return err
	}
	for _, slot := range record.Config.Slots {
		path := func(name string) string { return filepath.Join(directory, name) }
		tls := natscell.TLSFiles{CAFile: path("ca.pem"), CertFile: path(slot.Name + "-tls-cert.pem"), KeyFile: path(slot.Name + "-tls-key.pem")}
		routes := make([]string, 0, 2)
		for _, peer := range record.Config.Slots {
			if peer.Name != slot.Name {
				routes = append(routes, "nats-route://"+peer.PrivateIP+":6222")
			}
		}
		cfg := natscell.Config{Cell: record.Config.Cell, Instance: slot.Name, Replicas: 3, ClientRole: "controller",
			CredentialsFile: path(slot.Name + ".creds"), TLS: tls, Embedded: &natscell.Embedded{
				Host: slot.PrivateIP, Port: 4222, RouteHost: slot.PrivateIP, RoutePort: 6222, Routes: routes,
				StoreDir: path("unused-" + slot.Name), TLS: tls, RouteTLS: tls, RouteUser: "ts-route", RoutePasswordFile: path("route-password"),
				OperatorJWTFile: path("operator.jwt"), SystemJWTFile: path("system.jwt"), CellJWTFile: path("cell.jwt"),
				SystemCredentialsFile: path("system.creds"), TicketPublicKeyFile: path("ticket.pub"),
				BrokerIDs: []string{"controller-a", "controller-b", "controller-c"}}}
		if err := natscell.ValidateProductionCredentials(cfg); err != nil {
			return fmt.Errorf("controller %s credential validation: %w", slot.Name, err)
		}
		certPEM, err := readOwnedFile(path(slot.Name+"-tls-cert.pem"), 64<<10)
		if err != nil {
			return err
		}
		block, _ := pem.Decode(certPEM)
		if block == nil {
			return ErrMaterial
		}
		cert, err := x509.ParseCertificate(block.Bytes)
		if err != nil || !slices.ContainsFunc(cert.IPAddresses, func(ip net.IP) bool { return ip.Equal(net.ParseIP(slot.PrivateIP)) }) {
			return ErrMaterial
		}
	}
	return nil
}

func validateSignerFiles(directory string, record Record) error {
	read := func(name string) ([]byte, error) { return readOwnedFile(filepath.Join(directory, name), 64<<10) }
	issuerSeed, err := read("host-nats-issuer.seed")
	if err != nil {
		return ErrMaterial
	}
	issuer, err := nkeys.FromSeed(issuerSeed)
	clear(issuerSeed)
	if err != nil {
		return ErrMaterial
	}
	issuerID, err := issuer.PublicKey()
	if err != nil || issuerID != record.Public.HostNATSIssuerNKey {
		issuer.Wipe()
		return ErrMaterial
	}
	role, err := roleScope(issuer)
	issuer.Wipe()
	if err != nil {
		return ErrMaterial
	}
	cellWire, err := read("cell.jwt")
	if err != nil {
		return ErrMaterial
	}
	cellClaim, err := jwt.DecodeAccountClaims(string(cellWire))
	clear(cellWire)
	if err != nil {
		return ErrMaterial
	}
	scope, ok := cellClaim.SigningKeys.GetScope(issuerID)
	hostScope, ok := scope.(*jwt.UserScope)
	// Material generated before TS-663 has no role signer.
	bound, hasRole := cellClaim.SigningKeys.GetScope(role.Key)
	roleBound, _ := bound.(*jwt.UserScope)
	controllerScope, hasController := cellClaim.SigningKeys.GetScope(record.Public.ControllerAccountSignerNKey)
	// A link signer, when configured, is the only other scoped key.
	hasLink := record.Config.LinkSigner != ""
	if hasLink {
		if _, linked := cellClaim.SigningKeys.GetScope(record.Config.LinkSigner); !linked {
			return ErrMaterial
		}
	}
	if !ok || !reflect.DeepEqual(hostScope, expectedHostScope(record.Config.Cell, issuerID)) ||
		hasRole && !reflect.DeepEqual(roleBound, role) || !hasController || controllerScope != nil ||
		len(cellClaim.SigningKeys) != 2+boolInt(hasRole)+boolInt(hasLink) {
		return ErrMaterial
	}
	controller, err := loadRecordedControllerIssuer(record, read, time.Now())
	if err != nil {
		return err
	}
	controller.Wipe()
	operatorWire, err := read("operator.creds")
	if err != nil {
		return ErrMaterial
	}
	operatorJWT, err := nkeys.ParseDecoratedJWT(operatorWire)
	if err != nil {
		clear(operatorWire)
		return ErrMaterial
	}

func credentialUser(path string) (*jwt.UserClaims, string, error) {
	data, err := readPrivateFile(path, 64<<10)
	if err != nil {
		return nil, "", err
	}
	defer clear(data)
	return credentialUserBytes(data)
}

func credentialUserBytes(data []byte) (*jwt.UserClaims, string, error) {
	raw, err := nkeys.ParseDecoratedJWT(data)
	if err != nil {
		return nil, "", err
	}
	claim, err := jwt.DecodeUserClaims(raw)
	if err != nil {
		return nil, "", err
	}
	pair, err := nkeys.ParseDecoratedUserNKey(data)
	if err != nil {
		return nil, "", err
	}
	defer pair.Wipe()
	public, err := pair.PublicKey()
	if err != nil || public != claim.Subject {
		return nil, "", errors.New("regional credential seed and user JWT differ")
	}
	if claim.BearerToken || claim.ProxyRequired || len(claim.Src) != 0 ||
		len(claim.AllowedConnectionTypes) != 0 && !claim.AllowedConnectionTypes.Contains(jwt.ConnectionTypeInProcess) {
		return nil, "", errors.New("regional JWT depends on client metadata unavailable through the bridge")
	}
	return claim, public, nil
}

func ValidateBrokerControllerCredentials(path, cell, broker string) error {
	data, err := readPrivateFile(path, 64<<10)
	if err != nil {
		return fmt.Errorf("broker controller credentials: %w", err)
	}
	defer clear(data)
	return ValidateBrokerControllerCredentialBytes(data, cell, broker)
}

func ValidateBrokerControllerCredentialBytes(data []byte, cell, broker string) error {
	if !cellName.MatchString(cell) || !cellName.MatchString(broker) {
		return errors.New("broker controller credential cell or instance is invalid")
	}
	claim, public, err := credentialUserBytes(data)
	if err != nil {
		return fmt.Errorf("broker controller credentials: %w", err)
	}
	ticket := protocol.Broker(cell, "ticket", ">")
	fencePublish := protocol.Broker(cell, "fence", ">")
	fenceReceive := protocol.Broker(cell, "fence", broker)
	if !slices.Contains(claim.Pub.Allow, ticket) || !slices.Contains(claim.Pub.Allow, fencePublish) ||
		!slices.Contains(claim.Sub.Allow, ticket) || !slices.Contains(claim.Sub.Allow, fenceReceive) {
		return errors.New("broker controller credentials lack ticket or instance-bound fence grants")
	}
	allowedSubscriptions := map[string]bool{
		inboxPrefix(cell, public) + ".>": true,
		ticket:                           true, fenceReceive: true,
	}
	for _, subject := range ControllerSubscriptions(cell) {
		allowedSubscriptions[subject] = true
	}
	for _, subject := range GlobalControllerRequests() {
		allowedSubscriptions[subject] = true
	}
	// Optional read-only member telemetry (observability snapshots). The
	// issuer does not grant it today; it is accepted, not required.
	allowedSubscriptions[protocol.ObservabilityGrant(cell)] = true
	for _, grant := range claim.Sub.Allow {
		if !allowedSubscriptions[grant] {
			return fmt.Errorf("broker controller credentials have unscoped subscription %q", grant)
		}
	}
	if !slices.Contains(claim.Sub.Allow, inboxPrefix(cell, public)+".>") ||
		!slices.Contains(claim.Sub.Allow, protocol.BrokerClaimApplySubject(cell)) ||
		!slices.Contains(claim.Sub.Allow, protocol.ManagedUpdatePrepareSubject(cell)) ||
		!slices.Contains(claim.Sub.Allow, protocol.BackupOperationSubject(cell)) ||
		!slices.Contains(claim.Sub.Allow, protocol.TerminalSubject(cell, ">")) ||
		len(claim.Pub.Deny) != 0 || len(claim.Sub.Deny) != 0 ||
		claim.Resp == nil || claim.Resp.MaxMsgs != 1 ||
		claim.Resp.Expires <= 0 || claim.Resp.Expires > 5*time.Second {
		return errors.New("broker controller credentials need a private inbox and one bounded response grant")
	}
	return nil
}

func ValidateGlobalControllerPermissions(cfg Config) error {
	switch {
	case cfg.CredentialsFile != "":
		claim, _, err := credentialUser(cfg.CredentialsFile)
		if err != nil {
			return fmt.Errorf("controller credentials: %w", err)
		}
		return globalPublishGranted(claim.Pub.Allow, claim.Pub.Deny)
	case cfg.NKeySeedFile != "" && cfg.Embedded != nil && len(cfg.Embedded.Users) != 0:
		data, err := readPrivateFile(cfg.NKeySeedFile, 4096)
		if err != nil {
			return fmt.Errorf("controller NKey seed: %w", err)
		}
		pair, err := nkeys.ParseDecoratedUserNKey(data)
		clear(data)
		if err != nil {
			return fmt.Errorf("controller NKey seed: %w", err)
		}
		public, err := pair.PublicKey()
		pair.Wipe()
		if err != nil {
			return err
		}
		for _, user := range cfg.Embedded.Users {
			if user.PublicKey == public {
				if user.Role != "controller" || !user.Global {
					return ErrMissingGlobalGrants
				}
				return nil
			}
		}
		return ErrMissingGlobalGrants
	}
	return nil
}

func ValidateGlobalControllerCredentialBytes(data []byte) error {
	claim, _, err := credentialUserBytes(data)
	if err != nil {
		return err
	}
	return globalPublishGranted(claim.Pub.Allow, claim.Pub.Deny)
}

func globalPublishGranted(allow, deny []string) error {
	for _, subject := range GlobalControllerPublishes() {
		if len(allow) != 0 && !grantsCover(allow, subject) || grantsTouch(deny, subject) {
			return fmt.Errorf("%w: %q", ErrMissingGlobalGrants, subject)
		}
	}
	return nil
}

func ValidateProductionCredentials(cfg Config) error {
	if cfg.Embedded == nil || cfg.ClientRole != "" && cfg.ClientRole != "controller" {
		return errors.New("controller credential preflight requires a production embedded broker")
	}
	if err := cfg.validate(); err != nil {
		return err
	}
	e := cfg.Embedded
	operator, systemRaw, cellRaw, _, cellID, err := loadOperatorAccounts(e)
	if err != nil {
		return err
	}
	system, err := jwt.DecodeAccountClaims(systemRaw)
	if err != nil {
		return fmt.Errorf("decode system account JWT: %w", err)
	}
	cell, err := jwt.DecodeAccountClaims(cellRaw)
	if err != nil {
		return fmt.Errorf("decode cell account JWT: %w", err)
	}
	for label, claim := range map[string]jwt.Claims{"operator": operator, "system": system, "cell": cell} {
		result := jwt.CreateValidationResults()
		claim.Validate(result)
		if result.IsBlocking(true) {
			return fmt.Errorf("%s JWT is not currently valid", label)
		}
	}
	if err := validateSystemCredentials(e.SystemCredentialsFile, cfg.Cell, cellID, system.Subject); err != nil {
		return err
	}
	systemUser, _, err := credentialUser(e.SystemCredentialsFile)
	if err != nil {
		return fmt.Errorf("system account credentials: %w", err)
	}
	controller, _, err := credentialUser(cfg.CredentialsFile)
	if err != nil || credentialAccount(controller) != cellID {
		return errors.New("controller credentials do not belong to the regional cell account")
	}
	for label, claim := range map[string]*jwt.UserClaims{"system": systemUser, "controller": controller} {
		result := jwt.CreateValidationResults()
		claim.Validate(result)
		if result.IsBlocking(true) {
			return fmt.Errorf("%s user JWT is not currently valid", label)
		}
	}
	if err := ValidateBrokerControllerCredentials(cfg.CredentialsFile, cfg.Cell, cfg.Instance); err != nil {
		return err
	}
	// The optional membership user is checked at admission, not first at
	// shutdown when it is needed for the metadata step-down.
	if e.MembershipCredentialsFile != "" {
		if err := ValidateMembershipCredentials(e.MembershipCredentialsFile, cfg.Cell, system.Subject); err != nil {
			return err
		}
	}
	for label, files := range map[string]TLSFiles{"client": cfg.TLS, "listener": e.TLS, "route": e.RouteTLS} {
		if err := validateCurrentTLSFiles(files, label); err != nil {
			return fmt.Errorf("%s TLS material: %w", label, err)
		}
	}
	if cfg.Replicas > 1 {
		password, err := readPrivateFile(e.RoutePasswordFile, 4096)
		if err != nil {
			return fmt.Errorf("NATS route secret: %w", err)
		}
		defer clear(password)
		if len(strings.TrimSpace(string(password))) < 16 {
			return errors.New("NATS route secret is too short")
		}
	}
	return nil
}

func Start(ctx context.Context, cfg Config) (_ *Runtime, err error) {
	return start(ctx, cfg, false)
}

func start(ctx context.Context, cfg Config, identityRekey bool) (_ *Runtime, err error) {
	if err := cfg.validate(); err != nil {
		return nil, err
	}
	r := &Runtime{cell: cfg.Cell}
	defer func() {
		if err != nil {
			_ = r.Close()
		}
	}()
	if cfg.Embedded != nil {
		options, optionsErr := serverOptionsForStart(cfg, identityRekey)
		if optionsErr != nil {
			return nil, optionsErr
		}
		r.server, err = server.NewServer(options)
		if err != nil {
			return nil, fmt.Errorf("create embedded NATS: %w", err)
		}
		if err := pinNodeIdentity(cfg.Embedded.StoreDir, cfg.Cell, cfg.Instance, r.server.NodeName()); err != nil {
			return nil, fmt.Errorf("pin embedded NATS Raft identity: %w", err)
		}
		r.server.SetLoggerV2(natsLogger{}, false, false, false)
		r.serverName = options.ServerName
		for _, id := range cfg.Embedded.BrokerIDs {
			r.brokerNames = append(r.brokerNames, ServerName(cfg.Cell, id))
		}
		go r.server.Start()
		if !serverReady(ctx, r.server) {
			return nil, errors.New("embedded NATS did not become ready")
		}
		cfg.URL = r.server.ClientURL()
		r.resolver = options.AccountResolver.(*accountResolver)
		r.operator = options.TrustedOperators[0]
		if _, err := r.server.LookupAccount(r.resolver.cell); err != nil {
			return nil, fmt.Errorf("load regional cell account: %w", err)
		}
	}
	options, err := clientOptions(cfg)
	if err != nil {
		return nil, err
	}
	if cfg.Embedded != nil {
		options = append(options, nats.InProcessServer(r.server))
	}
	if cfg.ClientRole == "host" {
		// A blackholed peer must be detected well inside the host's 25-second
		// execution window. nats.go otherwise waits two minutes between PINGs.
		options = append(options,
			nats.PingInterval(2*time.Second), nats.MaxPingsOutstanding(2),
			nats.ReconnectWait(500*time.Millisecond),
			nats.DisconnectErrHandler(func(conn *nats.Conn, cause error) {
				r.logHostConnection("disconnected", conn, cause)
			}),
			nats.ReconnectHandler(func(conn *nats.Conn) {
				r.logHostConnection("reconnected", conn, nil)
			}),
		)
	}
	connectCtx, cancel := context.WithTimeout(ctx, 15*time.Second)
	defer cancel()
	connected := make(chan struct{})
	var connectErr, forwardErr error
	go func() {
		connectURL := cfg.URL
		if cfg.Embedded == nil {
			if len(cfg.OperatorForward) != 0 {
				var selected string
				selected, _, forwardErr = operatorForwarding(cfg)
				if forwardErr != nil {
					close(connected)
					return
				}
				connectURL = selected
			}
			connectURL = bridgeClientURLs(connectURL)
		}
		r.conn, connectErr = nats.Connect(connectURL, options...)
		close(connected)
	}()
	select {
	case <-connectCtx.Done():
		// nats.Connect has a bounded timeout of its own; wait for the goroutine
		// before cleaning up to avoid a late client after server shutdown.
		<-connected
		if forwardErr != nil {
			return nil, forwardErr
		}
		return nil, unavailable{connectCtx.Err()}
	case <-connected:
	}
	if forwardErr != nil {
		return nil, forwardErr
	}
	if connectErr != nil {
		err := fmt.Errorf("connect regional NATS: %w", connectErr)
		if errors.Is(connectErr, nats.ErrAuthorization) {
			// The brokers answered and refused these credentials.
			return nil, err
		}
		return nil, unavailable{err}
	}
	if cfg.Embedded != nil {
		systemCfg := cfg
		systemCfg.NKeySeedFile = ""
		systemCfg.CredentialsFile = cfg.Embedded.SystemCredentialsFile
		systemOptions, optionErr := clientOptions(systemCfg)
		if optionErr != nil {
			return nil, fmt.Errorf("system account client: %w", optionErr)
		}
		systemOptions = append(systemOptions, nats.InProcessServer(r.server))
		r.systemConn, err = nats.Connect(cfg.URL, systemOptions...)
		if err != nil {
			return nil, fmt.Errorf("connect internal system account: %w", err)
		}
		r.brokerTLS, err = NewReloadingTLS(cfg.Embedded.TLS, "listener")
		if err != nil {
			return nil, err
		}
		if !identityRekey {
			r.bridge, err = startBridge(r.server, net.JoinHostPort(cfg.Embedded.Host, fmt.Sprint(cfg.Embedded.Port)),
				r.brokerTLS.ServerConfig(), r.resolver.cell)
			if err != nil {
				return nil, err
			}
		}
	}
	if cfg.ClientRole == "host" {
		r.logHostConnection("connected", r.conn, nil)
	}
	r.js, err = jetstream.New(r.conn)
	if err != nil {
		return nil, fmt.Errorf("open regional JetStream: %w", err)
	}
	// A new R3 cell cannot elect a JetStream metadata leader until its peers
	// have also started. The app calls WaitForCluster before any mutations.
	if cfg.Replicas == 1 && cfg.ClientRole != "host" {
		infoCtx, infoCancel := context.WithTimeout(ctx, 10*time.Second)
		defer infoCancel()
		if _, err := r.js.AccountInfo(infoCtx); err != nil {
			return nil, unavailable{fmt.Errorf("regional JetStream unavailable: %w", err)}
		}
	}
	return r, nil
}

func startBridge(s *server.Server, address string, tlsConfig *tls.Config, account string) (*Bridge, error) {
	if s == nil || tlsConfig == nil || account == "" {
		return nil, errors.New("production broker bridge is incomplete")
	}
	listener, err := tls.Listen("tcp", address, tlsConfig)
	if err != nil {
		return nil, fmt.Errorf("listen for regional broker clients: %w", err)
	}
	b := &Bridge{server: s, listener: listener, account: account, pairs: make(map[*bridgePair]struct{}), listeners: make(map[net.Listener]struct{})}
	go b.accept(listener)
	return b, nil
}

