func newLinkFixture(t *testing.T) linkFixture {
	t.Helper()
	root := t.TempDir()
	f := linkFixture{home: filepath.Join(root, "home"), spoke: filepath.Join(root, "spoke"), homeLink: filepath.Join(root, "home-link"), spokeLink: filepath.Join(root, "spoke-link"), now: time.Now().UTC().Truncate(time.Second)}
	cfg := testConfig()
	if _, err := Generate(f.home, cfg, f.now); err != nil {
		t.Fatal(err)
	}
	cfg.Cell, cfg.Region, cfg.ClusterID = "sfo", "us-sanjose-1", "00000000000000000000000002"
	if _, err := Generate(f.spoke, cfg, f.now); err != nil {
		t.Fatal(err)
	}
	nextSecond()
	var err error
	f.spokeRecord, err = GenerateLink(f.spoke, f.home, f.homeLink, f.spokeLink, f.now)
	if err != nil {
		t.Fatal(err)
	}
	f.homeRecord, err = LoadLink(f.homeLink, f.now)
	if err != nil {
		t.Fatal(err)
	}
	return f
}

func GenerateLink(materialDirectory, homeMaterialDirectory, homeLinkDirectory, directory string, now time.Time) (LinkRecord, error) {
	material, err := Load(materialDirectory)
	if err != nil {
		return LinkRecord{}, err
	}
	home, err := Load(homeMaterialDirectory)
	if err != nil || home.Config.Cell != natscell.LinkHome || material.Config.Environment != home.Config.Environment || material.Config.DeploymentID != home.Config.DeploymentID || now.IsZero() || now.Before(material.IssuedAt) || now.Before(home.IssuedAt) || !now.Before(material.ExpiresAt) || !now.Before(home.ExpiresAt) {
		return LinkRecord{}, ErrMaterial
	}
	isHome := material.Config.Cell == natscell.LinkHome
	if isHome && filepath.Clean(materialDirectory) != filepath.Clean(homeMaterialDirectory) || isHome && filepath.Clean(homeLinkDirectory) != filepath.Clean(directory) || !isHome && (nested(homeLinkDirectory, directory) || nested(directory, homeLinkDirectory)) {
		return LinkRecord{}, ErrMaterial
	}
	for _, source := range []string{materialDirectory, homeMaterialDirectory} {
		if !filepath.IsAbs(directory) || secureParents(directory) != nil || nested(source, directory) || nested(directory, source) {
			return LinkRecord{}, ErrMaterial
		}
	}
	if err := ValidateLive(materialDirectory, material); err != nil {
		return LinkRecord{}, err
	}
	if err := ValidateLive(homeMaterialDirectory, home); err != nil {
		return LinkRecord{}, err
	}
	sourceDigest, err := metadataDigest(materialDirectory)
	if err != nil {
		return LinkRecord{}, err
	}
	homeDigest, err := metadataDigest(homeMaterialDirectory)
	if err != nil {
		return LinkRecord{}, err
	}
	var homeLink LinkRecord
	homeLinkDigest := ""
	if !isHome {
		homeLink, err = GenerateLink(homeMaterialDirectory, homeMaterialDirectory, homeLinkDirectory, homeLinkDirectory, now)
		if err != nil {
			return LinkRecord{}, err
		}
		homeLinkDigest, err = metadataDigest(homeLinkDirectory)
		if err != nil {
			return LinkRecord{}, err
		}
	}
	if _, err := os.Lstat(directory); err == nil {
		record, err := LoadLink(directory, now)
		if err != nil || record.SourceSHA256 != sourceDigest || record.HomeSHA256 != homeDigest || record.HomeLinkSHA256 != homeLinkDigest || !reflect.DeepEqual(record.Config, material.Config) || !reflect.DeepEqual(record.Public, material.Public) || record.HomeAccount != home.Public.CellAccountNKey || !isHome && record.Signer != homeLink.Signer {
			return LinkRecord{}, ErrMaterial
		}
		return record, nil
	} else if !errors.Is(err, os.ErrNotExist) {
		return LinkRecord{}, ErrMaterial
	}
	var homeClaim *jwt.AccountClaims
	if isHome {
		raw, err := readOwnedFile(filepath.Join(materialDirectory, "cell.jwt"), 64<<10)
		if err != nil {
			return LinkRecord{}, err
		}
		homeClaim, err = jwt.DecodeAccountClaims(string(raw))
		if err != nil || homeClaim.Subject != home.Public.CellAccountNKey || len(homeClaim.Imports) != 0 || len(homeClaim.Exports) != 0 || len(homeClaim.Mappings) != 0 || material.Config.LinkSigner != "" {
			return LinkRecord{}, ErrMaterial
		}
		if homeClaim.IssuedAt >= time.Now().Unix() {
			return LinkRecord{}, fmt.Errorf("%w: home cell claim was issued this second; retry after its issuance second", ErrMaterial)
		}
	}
	// Publish complete source bytes atomically; a crash before publication grants no authority.
	staging, err := os.MkdirTemp(filepath.Dir(directory), ".link-material-")
	if err != nil {
		return LinkRecord{}, err
	}
	defer os.RemoveAll(staging)
	files := map[string][]byte{}
	defer func() {
		for _, body := range files {
			clear(body)
		}
	}()
	record := LinkRecord{SchemaVersion: 1, Config: material.Config, Public: material.Public, IssuedAt: now.UTC(), ExpiresAt: minTime(material.ExpiresAt, home.ExpiresAt), SourceSHA256: sourceDigest, HomeSHA256: homeDigest, HomeLinkSHA256: homeLinkDigest, HomeAccount: home.Public.CellAccountNKey}
	var signer nkeys.KeyPair
	if isHome {
		signer, err = nkeys.CreateAccount()
		if err != nil {
			return LinkRecord{}, err
		}
		files["issuer-link.seed"], err = signer.Seed()
	} else {
		record.ExpiresAt = minTime(record.ExpiresAt, homeLink.ExpiresAt)
		seed, readErr := readOwnedFile(filepath.Join(homeLinkDirectory, "issuer-link.seed"), 4096)
		if readErr != nil {
			return LinkRecord{}, readErr
		}
		signer, err = nkeys.FromSeed(seed)
		clear(seed)
	}
	if err != nil {
		return LinkRecord{}, err
	}
	defer signer.Wipe()
	record.Signer, err = signer.PublicKey()
	if err != nil {
		return LinkRecord{}, err
	}
	if isHome {
		claim := homeClaim
		previousIssue := claim.IssuedAt
		natscell.ApplyLink(claim, record.Signer)
		seed, readErr := readOwnedFile(filepath.Join(materialDirectory, "issuer-operator.seed"), 4096)
		if readErr != nil {
			return LinkRecord{}, readErr
		}
		operator, decodeErr := nkeys.FromSeed(seed)
		clear(seed)
		if decodeErr != nil {
			return LinkRecord{}, decodeErr
		}
		claim.IssuedAt, claim.Expires = now.Unix(), record.ExpiresAt.Unix()
		encoded, encodeErr := claim.Encode(operator)
		operator.Wipe()
		if encodeErr != nil {
			return LinkRecord{}, encodeErr
		}
		if claim.IssuedAt <= previousIssue {
			return LinkRecord{}, ErrMaterial
		}
		files["link-cell.jwt"] = []byte(encoded)
	} else {
		files[bootstrap.LinkCredentialsFile], err = natscell.IssueLinkUser(signer, record.HomeAccount, material.Config.Cell, now, record.ExpiresAt)
		if err != nil {
			return LinkRecord{}, err
		}
	}
	files["interregion-ca.pem"], err = readOwnedFile(filepath.Join(homeMaterialDirectory, "ca.pem"), 64<<10)
	if err != nil {
		return LinkRecord{}, err
	}
	ca, key, err := linkCA(files["interregion-ca.pem"], filepath.Join(homeMaterialDirectory, "issuer-ca.key"))
	if err != nil {
		return LinkRecord{}, err
	}
	for _, slot := range material.Config.Slots {
		template := &x509.Certificate{Subject: pkix.Name{CommonName: material.Config.Cell + " " + slot.Name + " link"}, NotBefore: now.Add(-time.Minute), NotAfter: record.ExpiresAt, KeyUsage: x509.KeyUsageDigitalSignature, ExtKeyUsage: []x509.ExtKeyUsage{x509.ExtKeyUsageClientAuth}, DNSNames: []string{InterRegionLeafName(material.Config.Cell)}}
		if isHome {
			template.ExtKeyUsage = append(template.ExtKeyUsage, x509.ExtKeyUsageServerAuth)
			template.DNSNames = []string{natscell.LinkServerName}
		}
		certName, keyName := bootstrap.InterRegionTLSFiles(slot.Name)
		files[certName], files[keyName], _, _, err = interRegionCertificate(template, ca, key)
		if err != nil {
			return LinkRecord{}, err
		}
	}
	for _, name := range slices.Sorted(maps.Keys(files)) {
		purpose, slot := linkPurpose(name)
		body := files[name]
		if len(body) == 0 || len(body) > maxInterRegionFile {
			return LinkRecord{}, ErrMaterial
		}
		record.Files = append(record.Files, File{Name: name, Purpose: purpose, Slot: slot, SHA256: digest(body), MaxBytes: int64(len(body))})
		if err := writeOnce(filepath.Join(staging, name), body); err != nil {
			return LinkRecord{}, err
		}
	}
	wire, err := json.Marshal(record)
	if err != nil {
		return LinkRecord{}, err
	}
	if err := writeOnce(filepath.Join(staging, metadataName), wire); err != nil {
		return LinkRecord{}, err
	}
	if err := writeOnce(filepath.Join(staging, readyName), []byte(digest(wire)+"\n")); err != nil {
		return LinkRecord{}, err
	}
	if err := syncDirectory(staging); err != nil {
		return LinkRecord{}, err
	}
	if err := unix.Renameat2(unix.AT_FDCWD, staging, unix.AT_FDCWD, directory, unix.RENAME_NOREPLACE); err != nil && !errors.Is(err, unix.EEXIST) {
		return LinkRecord{}, err
	}
	if err := syncDirectory(filepath.Dir(directory)); err != nil {
		return LinkRecord{}, err
	}
	return GenerateLink(materialDirectory, homeMaterialDirectory, homeLinkDirectory, directory, now)
}

func LoadLink(directory string, now time.Time) (LinkRecord, error) {
	if !filepath.IsAbs(directory) || secureParents(directory) != nil || secureDirectory(directory) != nil {
		return LinkRecord{}, ErrMaterial
	}
	wire, err := readOwnedFile(filepath.Join(directory, metadataName), 1<<20)
	if err != nil {
		return LinkRecord{}, err
	}
	ready, err := readOwnedFile(filepath.Join(directory, readyName), 128)
	if err != nil || string(ready) != digest(wire)+"\n" {
		return LinkRecord{}, ErrMaterial
	}
	var record LinkRecord
	if json.Unmarshal(wire, &record, json.RejectUnknownMembers(true)) != nil || record.SchemaVersion != 1 || record.Config.validate() != nil || len(record.SourceSHA256) != 64 || len(record.HomeSHA256) != 64 || !nkeys.IsValidPublicAccountKey(record.HomeAccount) || !nkeys.IsValidPublicAccountKey(record.Signer) || record.Signer == record.HomeAccount || now.Before(record.IssuedAt) || !now.Before(record.ExpiresAt) {
		return LinkRecord{}, ErrMaterial
	}
	home := record.Config.Cell == natscell.LinkHome
	expected := map[string]bool{"interregion-ca.pem": true}
	if home {
		expected["link-cell.jwt"], expected["issuer-link.seed"] = true, true
	} else {
		expected[bootstrap.LinkCredentialsFile] = true
		if len(record.HomeLinkSHA256) != 64 {
			return LinkRecord{}, ErrMaterial
		}
	}
	for _, slot := range record.Config.Slots {
		cert, key := bootstrap.InterRegionTLSFiles(slot.Name)
		expected[cert], expected[key] = true, true
	}
	if len(record.Files) != len(expected) {
		return LinkRecord{}, ErrMaterial
	}
	files := map[string][]byte{}
	defer func() {
		for _, body := range files {
			clear(body)
		}
	}()
	allowed := map[string]bool{metadataName: true, readyName: true, journalName: true, journalTempName: true, journalLockName: true}
	for _, file := range record.Files {
		purpose, slot := linkPurpose(file.Name)
		if !expected[file.Name] || files[file.Name] != nil || purpose != file.Purpose || slot != file.Slot || file.MaxBytes <= 0 || file.MaxBytes > maxInterRegionFile {
			return LinkRecord{}, ErrMaterial
		}
		body, err := readOwnedFile(filepath.Join(directory, file.Name), file.MaxBytes)
		if err != nil || int64(len(body)) != file.MaxBytes || digest(body) != file.SHA256 {
			clear(body)
			return LinkRecord{}, ErrMaterial
		}
		files[file.Name] = body
		allowed[file.Name] = true
	}
	entries, err := os.ReadDir(directory)
	if err != nil {
		return LinkRecord{}, err
	}
	for _, entry := range entries {
		if !allowed[entry.Name()] {
			return LinkRecord{}, ErrMaterial
		}
	}
	if home {
		claim, err := jwt.DecodeAccountClaims(string(files["link-cell.jwt"]))
		if err != nil || claim.Subject != record.HomeAccount || claim.Issuer != record.Public.OperatorNKey || natscell.VerifyLinkScope(claim) != nil {
			return LinkRecord{}, ErrMaterial
		}
		if scope, ok := claim.SigningKeys.GetScope(record.Signer); !ok || !reflect.DeepEqual(scope, natscell.LinkScope(record.Signer)) {
			return LinkRecord{}, ErrMaterial
		}
		signer, err := nkeys.FromSeed(files["issuer-link.seed"])
		if err != nil {
			return LinkRecord{}, ErrMaterial
		}
		public, err := signer.PublicKey()
		signer.Wipe()
		if err != nil || public != record.Signer {
			return LinkRecord{}, ErrMaterial
		}
	} else {
		if natscell.ValidateLinkCredentialBytes(files[bootstrap.LinkCredentialsFile], record.Config.Cell) != nil {
			return LinkRecord{}, ErrMaterial
		}
		raw, err := jwt.ParseDecoratedJWT(files[bootstrap.LinkCredentialsFile])
		if err != nil {
			return LinkRecord{}, ErrMaterial
		}
		claim, err := jwt.DecodeUserClaims(raw)
		if err != nil || claim.Issuer != record.Signer || claim.IssuerAccount != record.HomeAccount {
			return LinkRecord{}, ErrMaterial
		}
	}
	roots := x509.NewCertPool()
	if !roots.AppendCertsFromPEM(files["interregion-ca.pem"]) {
		return LinkRecord{}, ErrMaterial
	}
	for _, slot := range record.Config.Slots {
		cert, key := bootstrap.InterRegionTLSFiles(slot.Name)
		pair, err := tls.X509KeyPair(files[cert], files[key])
		if err != nil {
			return LinkRecord{}, ErrMaterial
		}
		leaf, err := x509.ParseCertificate(pair.Certificate[0])
		if err != nil {
			return LinkRecord{}, ErrMaterial
		}
		usages := []x509.ExtKeyUsage{x509.ExtKeyUsageClientAuth}
		if home {
			usages = append(usages, x509.ExtKeyUsageServerAuth)
		}
		if _, err := leaf.Verify(x509.VerifyOptions{Roots: roots, CurrentTime: now, DNSName: InterRegionLeafName(record.Config.Cell), KeyUsages: usages}); err != nil || leaf.IsCA || leaf.NotAfter.After(record.ExpiresAt) {
			return LinkRecord{}, ErrMaterial
		}
	}
	return record, nil
}

func RenderLink(record LinkRecord, slot, directory string) (natscell.Link, error) {
	if !filepath.IsAbs(directory) || !slices.ContainsFunc(record.Config.Slots, func(s Slot) bool { return s.Name == slot }) {
		return natscell.Link{}, ErrMaterial
	}
	cert, key := bootstrap.InterRegionTLSFiles(slot)
	link := natscell.Link{TLS: natscell.TLSFiles{CAFile: filepath.Join(directory, "interregion-ca.pem"), CertFile: filepath.Join(directory, cert), KeyFile: filepath.Join(directory, key)}}
	if record.Config.Cell != natscell.LinkHome {
		link.CredentialsFile = filepath.Join(directory, bootstrap.LinkCredentialsFile)
	}
	return link, nil
}

func Start(ctx context.Context, cfg Config) (_ *Runtime, err error) {
	return start(ctx, cfg, false)
}

func start(ctx context.Context, cfg Config, identityRekey bool) (_ *Runtime, err error) {
	if err := cfg.validate(); err != nil {
		return nil, err
	}
	r := &Runtime{cell: cfg.Cell}
	defer func() {
		if err != nil {
			_ = r.Close()
		}
	}()
	if cfg.Embedded != nil {
		options, optionsErr := serverOptionsForStart(cfg, identityRekey)
		if optionsErr != nil {
			return nil, optionsErr
		}
		r.server, err = server.NewServer(options)
		if err != nil {
			return nil, fmt.Errorf("create embedded NATS: %w", err)
		}
		if err := pinNodeIdentity(cfg.Embedded.StoreDir, cfg.Cell, cfg.Instance, r.server.NodeName()); err != nil {
			return nil, fmt.Errorf("pin embedded NATS Raft identity: %w", err)
		}
		r.server.SetLoggerV2(natsLogger{}, false, false, false)
		r.serverName = options.ServerName
		for _, id := range cfg.Embedded.BrokerIDs {
			r.brokerNames = append(r.brokerNames, ServerName(cfg.Cell, id))
		}
		go r.server.Start()
		if !serverReady(ctx, r.server) {
			return nil, errors.New("embedded NATS did not become ready")
		}
		cfg.URL = r.server.ClientURL()
		r.resolver = options.AccountResolver.(*accountResolver)
		r.operator = options.TrustedOperators[0]
		if _, err := r.server.LookupAccount(r.resolver.cell); err != nil {
			return nil, fmt.Errorf("load regional cell account: %w", err)
		}
	}
	options, err := clientOptions(cfg)
	if err != nil {
		return nil, err
	}
	if cfg.Embedded != nil {
		options = append(options, nats.InProcessServer(r.server))
	}
	if cfg.ClientRole == "host" {
		// A blackholed peer must be detected well inside the host's 25-second
		// execution window. nats.go otherwise waits two minutes between PINGs.
		options = append(options,
			nats.PingInterval(2*time.Second), nats.MaxPingsOutstanding(2),
			nats.ReconnectWait(500*time.Millisecond),
			nats.DisconnectErrHandler(func(conn *nats.Conn, cause error) {
				r.logHostConnection("disconnected", conn, cause)
			}),
			nats.ReconnectHandler(func(conn *nats.Conn) {
				r.logHostConnection("reconnected", conn, nil)
			}),
		)
	}
	connectCtx, cancel := context.WithTimeout(ctx, 15*time.Second)
	defer cancel()
	connected := make(chan struct{})
	var connectErr, forwardErr error
	go func() {
		connectURL := cfg.URL
		if cfg.Embedded == nil {
			if len(cfg.OperatorForward) != 0 {
				var selected string
				selected, _, forwardErr = operatorForwarding(cfg)
				if forwardErr != nil {
					close(connected)
					return
				}
				connectURL = selected
			}
			connectURL = bridgeClientURLs(connectURL)
		}
		r.conn, connectErr = nats.Connect(connectURL, options...)
		close(connected)
	}()
	select {
	case <-connectCtx.Done():
		// nats.Connect has a bounded timeout of its own; wait for the goroutine
		// before cleaning up to avoid a late client after server shutdown.
		<-connected
		if forwardErr != nil {
			return nil, forwardErr
		}
		return nil, unavailable{connectCtx.Err()}
	case <-connected:
	}
	if forwardErr != nil {
		return nil, forwardErr
	}
	if connectErr != nil {
		err := fmt.Errorf("connect regional NATS: %w", connectErr)
		if errors.Is(connectErr, nats.ErrAuthorization) {
			// The brokers answered and refused these credentials.
			return nil, err
		}
		return nil, unavailable{err}
	}
	if cfg.Embedded != nil {
		systemCfg := cfg
		systemCfg.NKeySeedFile = ""
		systemCfg.CredentialsFile = cfg.Embedded.SystemCredentialsFile
		systemOptions, optionErr := clientOptions(systemCfg)
		if optionErr != nil {
			return nil, fmt.Errorf("system account client: %w", optionErr)
		}
		systemOptions = append(systemOptions, nats.InProcessServer(r.server))
		r.systemConn, err = nats.Connect(cfg.URL, systemOptions...)
		if err != nil {
			return nil, fmt.Errorf("connect internal system account: %w", err)
		}
		r.brokerTLS, err = NewReloadingTLS(cfg.Embedded.TLS, "listener")
		if err != nil {
			return nil, err
		}
		if !identityRekey {
			r.bridge, err = startBridge(r.server, net.JoinHostPort(cfg.Embedded.Host, fmt.Sprint(cfg.Embedded.Port)),
				r.brokerTLS.ServerConfig(), r.resolver.cell)
			if err != nil {
				return nil, err
			}
		}
	}
	if cfg.ClientRole == "host" {
		r.logHostConnection("connected", r.conn, nil)
	}
	r.js, err = jetstream.New(r.conn)
	if err != nil {
		return nil, fmt.Errorf("open regional JetStream: %w", err)
	}
	// A new R3 cell cannot elect a JetStream metadata leader until its peers
	// have also started. The app calls WaitForCluster before any mutations.
	if cfg.Replicas == 1 && cfg.ClientRole != "host" {
		infoCtx, infoCancel := context.WithTimeout(ctx, 10*time.Second)
		defer infoCancel()
		if _, err := r.js.AccountInfo(infoCtx); err != nil {
			return nil, unavailable{fmt.Errorf("regional JetStream unavailable: %w", err)}
		}
	}
	return r, nil
}

func serverOptionsForStart(cfg Config, identityRekey bool) (*server.Options, error) {
	e := cfg.Embedded
	if err := os.MkdirAll(e.StoreDir, 0o700); err != nil {
		return nil, fmt.Errorf("create regional JetStream store: %w", err)
	}
	name := ServerName(cfg.Cell, cfg.Instance)
	if err := pinStoreIdentity(e.StoreDir, name, cfg.Cell+"-"+cfg.Instance); err != nil {
		return nil, err
	}
	options := &server.Options{
		ServerName:        name,
		Host:              e.Host,
		Port:              e.Port,
		JetStream:         true,
		JetStreamMaxStore: e.StoreLimitBytes(),
		StoreDir:          e.StoreDir,
		// JetStream clustering uses the system account to coordinate metadata.
		SystemAccount: "$SYS",
		Accounts:      []*server.Account{server.NewAccount("$SYS")},
		Cluster: server.ClusterOpts{
			Name: cfg.Cell,
			Host: e.RouteHost,
			Port: e.RoutePort,
		},
		LameDuckDuration:    lameDuckDuration,
		LameDuckGracePeriod: lameDuckGracePeriod,
		// NATS logs every failed reconnect to a lost route, gateway or leaf
		// at ERR by default: about one a second per pooled route while a peer
		// reboots. Report the first and then one a minute (TS-661).
		ReconnectErrorReports: reconnectErrorReports,
	}
	operator, systemJWT, cellJWT, systemID, cellID, err := loadOperatorAccounts(e)
	if err != nil {
		return nil, err
	}
	if err := validateSystemCredentials(e.SystemCredentialsFile, cfg.Cell, cellID, systemID); err != nil {
		return nil, err
	}
	controller, _, err := credentialUser(cfg.CredentialsFile)
	if err != nil || credentialAccount(controller) != cellID {
		return nil, errors.New("controller credentials do not belong to the regional cell account")
	}
	resolver := newAccountResolver(systemID, systemJWT, cellID, cellJWT)
	options.TrustedOperators = []*jwt.OperatorClaims{operator}
	options.SystemAccount = systemID
	options.Accounts = nil
	options.AccountResolver = resolver
	options.JetStreamDomain = cfg.Cell
	options.DontListen = true
	options.Cluster.NoAdvertise = true
	if e.InterRegion != nil {
		if err := interRegionServerOptions(cfg, options, resolver, operator); err != nil {
			return nil, err
		}
	}
	if e.Link != nil {
		if err := linkServerOptions(cfg, options, resolver); err != nil {
			return nil, err
		}
	}
	if identityRekey && (e.InterRegion != nil || e.Link != nil) {
		options.LeafNode = server.LeafNodeOpts{}
	}
	if cfg.Replicas > 1 {
		for _, raw := range e.Routes {
			route, err := url.Parse(raw)
			if err != nil || route.Host == "" || route.User != nil || route.Scheme != "nats-route" {
				return nil, fmt.Errorf("invalid NATS route %q", raw)
			}
			options.Routes = append(options.Routes, route)
		}
	}
	if cfg.Replicas > 1 && e.RouteTLS.complete() {
		// Routes reload a renewed leaf or CA bundle on their next handshake.
		routeTLS, err := NewReloadingTLS(e.RouteTLS, "route")
		if err != nil {
			return nil, err
		}
		options.Cluster.TLSConfig = routeTLS.PeerConfig()
	}
	seenKeys := make(map[string]struct{}, len(e.Users))
	for _, user := range e.Users {
		if !nkeys.IsValidPublicUserKey(user.PublicKey) {
			return nil, errors.New("invalid user NKey in embedded NATS users")
		}
		if _, exists := seenKeys[user.PublicKey]; exists {
			return nil, errors.New("duplicate embedded NATS user key")
		}
		seenKeys[user.PublicKey] = struct{}{}
		permissions, err := userPermissions(cfg.Cell, user)
		if err != nil {
			return nil, err
		}
		options.Nkeys = append(options.Nkeys, &server.NkeyUser{Nkey: user.PublicKey, Permissions: permissions})
	}
	if e.RoutePasswordFile != "" {
		secret, err := readPrivateFile(e.RoutePasswordFile, 4096)
		if err != nil {
			return nil, fmt.Errorf("read NATS route secret: %w", err)
		}
		defer clear(secret)
		password := strings.TrimSpace(string(secret))
		if len(password) < 16 {
			return nil, errors.New("NATS route secret must be at least 16 bytes")
		}
		options.Cluster.Username = e.RouteUser
		options.Cluster.Password = password
		for _, route := range options.Routes {
			route.User = url.UserPassword(e.RouteUser, password)
		}
	}
	return options, nil
}

func loadTLS(files TLSFiles, serverSide bool) (*tls.Config, error) {
	key, err := readPrivateFile(files.KeyFile, 64<<10)
	if err != nil {
		return nil, fmt.Errorf("NATS TLS private key: %w", err)
	}
	clear(key)
	certificate, err := tls.LoadX509KeyPair(files.CertFile, files.KeyFile)
	if err != nil {
		return nil, fmt.Errorf("load NATS certificate: %w", err)
	}
	ca, err := os.ReadFile(files.CAFile)
	if err != nil {
		return nil, fmt.Errorf("load NATS CA: %w", err)
	}
	roots := x509.NewCertPool()
	if !roots.AppendCertsFromPEM(ca) {
		return nil, errors.New("NATS CA file has no certificates")
	}
	config := &tls.Config{MinVersion: tls.VersionTLS13, Certificates: []tls.Certificate{certificate}, RootCAs: roots}
	if serverSide {
		config.ClientCAs = roots
		config.ClientAuth = tls.RequireAndVerifyClientCert
	}
	return config, nil
}

func linkServerOptions(cfg Config, options *server.Options, resolver *accountResolver) error {
	link := cfg.Embedded.Link
	cellClaim, err := jwt.DecodeAccountClaims(resolver.claims[resolver.cell])
	if err != nil {
		return err
	}
	if err := verifyLinkAccount(cellClaim, cfg.Cell); err != nil {
		return err
	}
	// The link rides the cell account, so the leaf accounts are the cell's.
	resolver.interregion = resolver.cell
	resolver.linkCell = cfg.Cell
	options.LeafNode.NoAdvertise = true
	// Same fast stale-path detection as the interregion leaves.
	options.PingInterval, options.MaxPingsOut = 10*time.Second, 3
	if cfg.Cell == LinkHome {
		listenTLS, err := loadTLS(link.TLS, true)
		if err != nil {
			return fmt.Errorf("link listener TLS: %w", err)
		}
		options.LeafNode.Host = "0.0.0.0"
		options.LeafNode.Port = linkListenPort
		options.LeafNode.TLSConfig = listenTLS
		options.LeafNode.TLSTimeout = 5
		return nil
	}
	if err := validateLinkCredentials(link.CredentialsFile, cfg.Cell); err != nil {
		return fmt.Errorf("link credentials: %w", err)
	}
	remoteTLS, err := loadTLS(link.TLS, false)
	if err != nil {
		return fmt.Errorf("link TLS: %w", err)
	}
	remoteTLS.ServerName = linkServerName
	leaf := &server.RemoteLeafOpts{
		LocalAccount: resolver.cell, Credentials: link.CredentialsFile,
		TLS: true, TLSConfig: remoteTLS, TLSTimeout: 5, NoRandomize: true,
		// The home cannot push regional-only families either.
		DenyImports: []string{"$JS.API.>", "$KV.>", "$O.>", "$SYS.>", protocol.ControlRoot + ".>", protocol.BrokerRoot + ".>"},
	}
	for _, raw := range linkHomeURLs {
		parsed, err := url.Parse(raw)
		if err != nil {
			return err
		}
		leaf.URLs = append(leaf.URLs, parsed)
	}
	options.LeafNode.Remotes = append(options.LeafNode.Remotes, leaf)
	return nil
}

func (b *Bridge) OpenUntil(sequence uint64, rawJWT string, deadline time.Time) error {
	if b == nil || sequence == 0 || rawJWT == "" || !time.Now().Before(deadline) {
		return errors.New("broker bridge ticket is invalid or expired")
	}
	if _, err := b.server.LookupAccount(b.account); err != nil {
		return fmt.Errorf("load broker account: %w", err)
	}
	accountz, err := b.server.Accountz(&server.AccountzOptions{Account: b.account})
	if err != nil || accountz.Account == nil || accountz.Account.Jwt != rawJWT {
		return errors.New("broker account JWT was not applied locally")
	}
	b.mu.Lock()
	if b.closed || sequence < b.floor {
		b.mu.Unlock()
		return errors.New("broker bridge is closed or claim sequence is stale")
	}
	var pairs map[*bridgePair]struct{}
	if b.open && (b.sequence != sequence || b.jwt != rawJWT) {
		pairs = b.fenceLocked()
	}
	b.sequence, b.jwt, b.deadline, b.open = sequence, rawJWT, deadline, true
	if b.timer != nil {
		b.timer.Stop()
	}
	b.timer = time.AfterFunc(time.Until(deadline), func() {
		b.mu.Lock()
		var expired map[*bridgePair]struct{}
		if b.open && b.sequence == sequence && b.deadline.Equal(deadline) {
			expired = b.fenceLocked()
		}
		b.mu.Unlock()
		closeBridgeExternal(expired)
	})
	b.mu.Unlock()
	closeBridgeExternal(pairs)
	return nil
}

