func GenerateLink(materialDirectory, homeMaterialDirectory, homeLinkDirectory, directory string, now time.Time) (LinkRecord, error) {
	material, err := Load(materialDirectory)
	if err != nil {
		return LinkRecord{}, err
	}
	home, err := Load(homeMaterialDirectory)
	if err != nil || home.Config.Cell != natscell.LinkHome || material.Config.Environment != home.Config.Environment || material.Config.DeploymentID != home.Config.DeploymentID || now.IsZero() || now.Before(material.IssuedAt) || now.Before(home.IssuedAt) || !now.Before(material.ExpiresAt) || !now.Before(home.ExpiresAt) {
		return LinkRecord{}, ErrMaterial
	}
	isHome := material.Config.Cell == natscell.LinkHome
	if isHome && filepath.Clean(materialDirectory) != filepath.Clean(homeMaterialDirectory) || isHome && filepath.Clean(homeLinkDirectory) != filepath.Clean(directory) || !isHome && (nested(homeLinkDirectory, directory) || nested(directory, homeLinkDirectory)) {
		return LinkRecord{}, ErrMaterial
	}
	for _, source := range []string{materialDirectory, homeMaterialDirectory} {
		if !filepath.IsAbs(directory) || secureParents(directory) != nil || nested(source, directory) || nested(directory, source) {
			return LinkRecord{}, ErrMaterial
		}
	}
	if err := ValidateLive(materialDirectory, material); err != nil {
		return LinkRecord{}, err
	}
	if err := ValidateLive(homeMaterialDirectory, home); err != nil {
		return LinkRecord{}, err
	}
	sourceDigest, err := metadataDigest(materialDirectory)
	if err != nil {
		return LinkRecord{}, err
	}
	homeDigest, err := metadataDigest(homeMaterialDirectory)
	if err != nil {
		return LinkRecord{}, err
	}
	var homeLink LinkRecord
	homeLinkDigest := ""
	if !isHome {
		homeLink, err = GenerateLink(homeMaterialDirectory, homeMaterialDirectory, homeLinkDirectory, homeLinkDirectory, now)
		if err != nil {
			return LinkRecord{}, err
		}
		homeLinkDigest, err = metadataDigest(homeLinkDirectory)
		if err != nil {
			return LinkRecord{}, err
		}
	}
	if _, err := os.Lstat(directory); err == nil {
		record, err := LoadLink(directory, now)
		if err != nil || record.SourceSHA256 != sourceDigest || record.HomeSHA256 != homeDigest || record.HomeLinkSHA256 != homeLinkDigest || !reflect.DeepEqual(record.Config, material.Config) || !reflect.DeepEqual(record.Public, material.Public) || record.HomeAccount != home.Public.CellAccountNKey || !isHome && record.Signer != homeLink.Signer {
			return LinkRecord{}, ErrMaterial
		}
		return record, nil
	} else if !errors.Is(err, os.ErrNotExist) {
		return LinkRecord{}, ErrMaterial
	}
	var homeClaim *jwt.AccountClaims
	if isHome {
		raw, err := readOwnedFile(filepath.Join(materialDirectory, "cell.jwt"), 64<<10)
		if err != nil {
			return LinkRecord{}, err
		}
		homeClaim, err = jwt.DecodeAccountClaims(string(raw))
		if err != nil || homeClaim.Subject != home.Public.CellAccountNKey || len(homeClaim.Imports) != 0 || len(homeClaim.Exports) != 0 || len(homeClaim.Mappings) != 0 || material.Config.LinkSigner != "" {
			return LinkRecord{}, ErrMaterial
		}
		if homeClaim.IssuedAt >= time.Now().Unix() {
			return LinkRecord{}, fmt.Errorf("%w: home cell claim was issued this second; retry after its issuance second", ErrMaterial)
		}
	}
	// Publish complete source bytes atomically; a crash before publication grants no authority.
	staging, err := os.MkdirTemp(filepath.Dir(directory), ".link-material-")
	if err != nil {
		return LinkRecord{}, err
	}
	defer os.RemoveAll(staging)
	files := map[string][]byte{}
	defer func() {
		for _, body := range files {
			clear(body)
		}
	}()
	record := LinkRecord{SchemaVersion: 1, Config: material.Config, Public: material.Public, IssuedAt: now.UTC(), ExpiresAt: minTime(material.ExpiresAt, home.ExpiresAt), SourceSHA256: sourceDigest, HomeSHA256: homeDigest, HomeLinkSHA256: homeLinkDigest, HomeAccount: home.Public.CellAccountNKey}
	var signer nkeys.KeyPair
	if isHome {
		signer, err = nkeys.CreateAccount()
		if err != nil {
			return LinkRecord{}, err
		}
		files["issuer-link.seed"], err = signer.Seed()
	} else {
		record.ExpiresAt = minTime(record.ExpiresAt, homeLink.ExpiresAt)
		seed, readErr := readOwnedFile(filepath.Join(homeLinkDirectory, "issuer-link.seed"), 4096)
		if readErr != nil {
			return LinkRecord{}, readErr
		}
		signer, err = nkeys.FromSeed(seed)
		clear(seed)
	}
	if err != nil {
		return LinkRecord{}, err
	}
	defer signer.Wipe()
	record.Signer, err = signer.PublicKey()
	if err != nil {
		return LinkRecord{}, err
	}
	if isHome {
		claim := homeClaim
		previousIssue := claim.IssuedAt
		natscell.ApplyLink(claim, record.Signer)
		seed, readErr := readOwnedFile(filepath.Join(materialDirectory, "issuer-operator.seed"), 4096)
		if readErr != nil {
			return LinkRecord{}, readErr
		}
		operator, decodeErr := nkeys.FromSeed(seed)
		clear(seed)
		if decodeErr != nil {
			return LinkRecord{}, decodeErr
		}
		claim.IssuedAt, claim.Expires = now.Unix(), record.ExpiresAt.Unix()
		encoded, encodeErr := claim.Encode(operator)
		operator.Wipe()
		if encodeErr != nil {
			return LinkRecord{}, encodeErr
		}
		if claim.IssuedAt <= previousIssue {
			return LinkRecord{}, ErrMaterial
		}
		files["link-cell.jwt"] = []byte(encoded)
	} else {
		files[bootstrap.LinkCredentialsFile], err = natscell.IssueLinkUser(signer, record.HomeAccount, material.Config.Cell, now, record.ExpiresAt)
		if err != nil {
			return LinkRecord{}, err
		}
	}
	files["interregion-ca.pem"], err = readOwnedFile(filepath.Join(homeMaterialDirectory, "ca.pem"), 64<<10)
	if err != nil {
		return LinkRecord{}, err
	}
	ca, key, err := linkCA(files["interregion-ca.pem"], filepath.Join(homeMaterialDirectory, "issuer-ca.key"))
	if err != nil {
		return LinkRecord{}, err
	}
	for _, slot := range material.Config.Slots {
		template := &x509.Certificate{Subject: pkix.Name{CommonName: material.Config.Cell + " " + slot.Name + " link"}, NotBefore: now.Add(-time.Minute), NotAfter: record.ExpiresAt, KeyUsage: x509.KeyUsageDigitalSignature, ExtKeyUsage: []x509.ExtKeyUsage{x509.ExtKeyUsageClientAuth}, DNSNames: []string{InterRegionLeafName(material.Config.Cell)}}
		if isHome {
			template.ExtKeyUsage = append(template.ExtKeyUsage, x509.ExtKeyUsageServerAuth)
			template.DNSNames = []string{natscell.LinkServerName}
		}
		certName, keyName := bootstrap.InterRegionTLSFiles(slot.Name)
		files[certName], files[keyName], _, _, err = interRegionCertificate(template, ca, key)
		if err != nil {
			return LinkRecord{}, err
		}
	}
	for _, name := range slices.Sorted(maps.Keys(files)) {
		purpose, slot := linkPurpose(name)
		body := files[name]
		if len(body) == 0 || len(body) > maxInterRegionFile {
			return LinkRecord{}, ErrMaterial
		}
		record.Files = append(record.Files, File{Name: name, Purpose: purpose, Slot: slot, SHA256: digest(body), MaxBytes: int64(len(body))})
		if err := writeOnce(filepath.Join(staging, name), body); err != nil {
			return LinkRecord{}, err
		}
	}
	wire, err := json.Marshal(record)
	if err != nil {
		return LinkRecord{}, err
	}
	if err := writeOnce(filepath.Join(staging, metadataName), wire); err != nil {
		return LinkRecord{}, err
	}
	if err := writeOnce(filepath.Join(staging, readyName), []byte(digest(wire)+"\n")); err != nil {
		return LinkRecord{}, err
	}
	if err := syncDirectory(staging); err != nil {
		return LinkRecord{}, err
	}
	if err := unix.Renameat2(unix.AT_FDCWD, staging, unix.AT_FDCWD, directory, unix.RENAME_NOREPLACE); err != nil && !errors.Is(err, unix.EEXIST) {
		return LinkRecord{}, err
	}
	if err := syncDirectory(filepath.Dir(directory)); err != nil {
		return LinkRecord{}, err
	}
	return GenerateLink(materialDirectory, homeMaterialDirectory, homeLinkDirectory, directory, now)
}

func ProvisionLink(ctx context.Context, directory string, target VaultTarget, management VaultClient, bundles BundleClient, now time.Time) (Publication, error) {
	return provisionLink(ctx, directory, target, management, bundles, now, nil)
}

func ProvisionLinkDurable(ctx context.Context, directory string, target VaultTarget, management VaultClient, bundles BundleClient, now time.Time, checkpoint func([]byte) error) (Publication, error) {
	if checkpoint == nil {
		return Publication{}, ErrProvision
	}
	return provisionLink(ctx, directory, target, management, bundles, now, checkpoint)
}

func provisionLink(ctx context.Context, directory string, target VaultTarget, management VaultClient, bundles BundleClient, now time.Time, checkpoint func([]byte) error) (Publication, error) {
	record, err := LoadLink(directory, now)
	if err != nil || management == nil || bundles == nil || ctx.Err() != nil || target.validate(record.Config.Region) != nil {
		return Publication{}, ErrProvision
	}
	ctx, cancel := context.WithDeadline(ctx, record.ExpiresAt)
	defer cancel()
	fd, err := syscall.Open(filepath.Join(directory, journalLockName), syscall.O_RDWR|syscall.O_CREAT|syscall.O_NOFOLLOW|syscall.O_CLOEXEC, 0o600)
	if err != nil {
		return Publication{}, ErrProvision
	}
	lock := os.NewFile(uintptr(fd), journalLockName)
	defer lock.Close()
	if ownedRegular(filepath.Join(directory, journalLockName), 0, 0) != nil {
		return Publication{}, ErrProvision
	}
	if err := syscall.Flock(fd, syscall.LOCK_EX|syscall.LOCK_NB); err != nil {
		return Publication{}, ErrProvision
	}
	defer syscall.Flock(fd, syscall.LOCK_UN)
	materialDigest, err := metadataDigest(directory)
	if err != nil {
		return Publication{}, ErrProvision
	}
	state, err := loadJournal(ctx, directory, record.Record, target, materialDigest, checkpoint)
	if err != nil {
		return Publication{}, err
	}
	result := Publication{SchemaVersion: 1, Target: target, MaterialSHA256: materialDigest}
	for index := range state.Entries {
		entry := &state.Entries[index]
		file, ok := findFile(record.Record, entry.FileName)
		if !ok || ctx.Err() != nil {
			return Publication{}, ErrProvision
		}
		if err := publishOne(ctx, directory, target, record.Config.Region, management, bundles, file, entry, &state, now, checkpoint); err != nil {
			return Publication{}, err
		}
		result.References = append(result.References, PublicReference{SecretName: entry.Name, Reference: bootstrap.SecretReference{Purpose: file.Purpose, Slot: file.Slot, SecretOCID: entry.SecretOCID, VersionNumber: 1, SHA256: file.SHA256, MaxBytes: file.MaxBytes, TargetFile: file.Name}})
	}
	return result, nil
}

func (publication Publication) LinkGenerationReferences() []bootstrap.SecretReference {
	var refs []bootstrap.SecretReference
	for _, ref := range publication.References {
		if ref.Reference.Purpose == bootstrap.SecretInterRegion || ref.Reference.TargetFile == "link-cell.jwt" {
			reference := ref.Reference
			if reference.TargetFile == "link-cell.jwt" {
				reference.TargetFile = "cell.jwt"
			}
			refs = append(refs, reference)
		}
	}
	return refs
}

func ValidateLinkPublication(directory string, publication Publication, journalWire []byte, now time.Time) error {
	record, err := LoadLink(directory, now)
	if err != nil {
		return ErrProvision
	}
	return validatePublication(directory, record.Record, publication, journalWire)
}

func loadJournal(ctx context.Context, directory string, record Record, target VaultTarget, materialDigest string, checkpoint func([]byte) error) (journal, error) {
	path := filepath.Join(directory, journalName)
	wire, err := readOwnedFile(path, 1<<20)
	if err != nil {
		if _, statErr := os.Lstat(path); !errors.Is(statErr, os.ErrNotExist) {
			return journal{}, ErrProvision
		}
		state := journal{SchemaVersion: 1, Target: target, MaterialSHA256: materialDigest}
		for _, file := range record.Files {
			if file.Purpose == "owner-only" {
				continue
			}
			state.Entries = append(state.Entries, journalEntry{Name: secretName(record.Config, file), FileName: file.Name, RetryToken: uuid.New().String()})
		}
		if len(state.Entries) == 0 || len(state.Entries) > 64 {
			return journal{}, ErrProvision
		}
		if err := checkpointJournal(ctx, directory, state, checkpoint); err != nil {
			return journal{}, err
		}
		return state, nil
	}
	var state journal
	if err := json.Unmarshal(wire, &state); err != nil || state.SchemaVersion != 1 || state.Target != target ||
		state.MaterialSHA256 != materialDigest || len(state.Entries) == 0 || len(state.Entries) > 64 {
		return journal{}, ErrProvision
	}
	expected := 0
	for _, file := range record.Files {
		if file.Purpose != "owner-only" {
			expected++
		}
	}
	if len(state.Entries) != expected {
		return journal{}, ErrProvision
	}
	for index, entry := range state.Entries {
		file, ok := findFile(record, entry.FileName)
		if !ok || file.Purpose == "owner-only" || entry.Name != secretName(record.Config, file) ||
			entry.Verified && !regionalResourceOCID(entry.SecretOCID, "vaultsecret", record.Config.Region) ||
			entry.SecretOCID != "" && !regionalResourceOCID(entry.SecretOCID, "vaultsecret", record.Config.Region) ||
			entry.Verified && entry.SentAt.IsZero() || entry.SecretOCID != "" && !entry.Verified ||
			!entry.SentAt.IsZero() && entry.SentAt.Before(record.IssuedAt) {
			return journal{}, ErrProvision
		}
		if _, err := uuid.Parse(entry.RetryToken); err != nil {
			return journal{}, ErrProvision
		}
		if index > 0 && state.Entries[index-1].FileName >= entry.FileName {
			return journal{}, ErrProvision
		}
	}
	if err := checkpointJournal(ctx, directory, state, checkpoint); err != nil {
		return journal{}, err
	}
	return state, nil
}

func checkpointJournal(ctx context.Context, directory string, state journal, checkpoint func([]byte) error) error {
	if err := saveJournal(ctx, directory, state); err != nil {
		return err
	}
	if checkpoint == nil {
		return nil
	}
	wire, err := readOwnedFile(filepath.Join(directory, journalName), 1<<20)
	if err != nil {
		return err
	}
	defer clear(wire)
	if err := GuardPublication(ctx); err != nil {
		return err
	}
	return checkpoint(wire)
}

func publishOne(ctx context.Context, directory string, target VaultTarget, region string, management VaultClient, bundles BundleClient,
	file File, entry *journalEntry, state *journal, now time.Time, checkpoint func([]byte) error) error {
	id, found, err := lookup(ctx, target, region, entry.Name, management)
	if err != nil {
		return ErrProvision
	}
	if found {
		if entry.SentAt.IsZero() {
			return ErrProvision
		}
		if entry.SecretOCID != "" && entry.SecretOCID != id {
			return ErrProvision
		}
		if err := verifyBundle(ctx, target, id, entry.Name, file, management, bundles); err != nil {
			return ErrProvision
		}
		entry.SecretOCID, entry.Verified = id, true
		return checkpointJournal(ctx, directory, *state, checkpoint)
	}
	if entry.Verified || entry.SecretOCID != "" || !entry.SentAt.IsZero() && (now.Before(entry.SentAt) || now.Sub(entry.SentAt) >= retryWindow) {
		return ErrProvision
	}
	if entry.SentAt.IsZero() {
		entry.SentAt = now.UTC()
		if err := checkpointJournal(ctx, directory, *state, checkpoint); err != nil {
			return err
		}
	}
	if ctx.Err() != nil {
		return ErrProvision
	}
	body, err := readOwnedFile(filepath.Join(directory, file.Name), file.MaxBytes)
	if err != nil || digest(body) != file.SHA256 {
		clear(body)
		return ErrProvision
	}
	encoded := base64.StdEncoding.EncodeToString(body)
	clear(body)
	if ctx.Err() != nil {
		return ErrProvision
	}
	if checkpoint != nil {
		if err := checkpointJournal(ctx, directory, *state, checkpoint); err != nil {
			encoded = ""
			return err
		}
	}
	response, err := management.CreateSecret(ociclient.RequestContext(ctx), ocivault.CreateSecretRequest{
		CreateSecretDetails: ocivault.CreateSecretDetails{
			CompartmentId: new(target.CompartmentOCID), VaultId: new(target.VaultOCID), KeyId: new(target.KMSKeyOCID),
			SecretName: new(entry.Name), Description: new("Initial TerraScale regional controller credential material."),
			SecretContent: ocivault.Base64SecretContentDetails{Content: new(encoded), Stage: ocivault.SecretContentDetailsStageCurrent}},
		OpcRetryToken: new(entry.RetryToken),
	})
	encoded = ""
	if err != nil || response.Id == nil || !regionalResourceOCID(*response.Id, "vaultsecret", region) {
		return ErrProvision
	}
	if err := verifyBundle(ctx, target, *response.Id, entry.Name, file, management, bundles); err != nil {
		return ErrProvision
	}
	entry.SecretOCID, entry.Verified = *response.Id, true
	return checkpointJournal(ctx, directory, *state, checkpoint)
}

func lookup(ctx context.Context, target VaultTarget, region, name string, client VaultClient) (string, bool, error) {
	var page *string
	var found string
	for range 32 {
		response, err := client.ListSecrets(ociclient.RequestContext(ctx), ocivault.ListSecretsRequest{CompartmentId: new(target.CompartmentOCID), VaultId: new(target.VaultOCID), Name: new(name), Page: page})
		if err != nil {
			return "", false, err
		}
		for _, item := range response.Items {
			if item.SecretName == nil || *item.SecretName != name || item.CompartmentId == nil || *item.CompartmentId != target.CompartmentOCID ||
				item.VaultId == nil || *item.VaultId != target.VaultOCID || item.Id == nil || item.LifecycleState != ocivault.SecretSummaryLifecycleStateActive &&
				item.LifecycleState != ocivault.SecretSummaryLifecycleStateCreating {
				return "", false, ErrProvision
			}
			if !regionalResourceOCID(*item.Id, "vaultsecret", region) || found != "" {
				return "", false, ErrProvision
			}
			found = *item.Id
		}
		if response.OpcNextPage == nil {
			return found, found != "", nil
		}
		page = response.OpcNextPage
	}
	return "", false, ErrProvision
}

func verifyBundle(ctx context.Context, target VaultTarget, id, name string, file File, management VaultClient, bundles BundleClient) error {
	deadline := time.Now().Add(time.Minute)
	for {
		response, err := management.GetSecret(ociclient.RequestContext(ctx), ocivault.GetSecretRequest{SecretId: new(id)})
		if err == nil && response.Id != nil && *response.Id == id && response.CompartmentId != nil &&
			*response.CompartmentId == target.CompartmentOCID && response.VaultId != nil && *response.VaultId == target.VaultOCID &&
			response.KeyId != nil && *response.KeyId == target.KMSKeyOCID &&
			response.SecretName != nil && *response.SecretName == name && response.LifecycleState == ocivault.SecretLifecycleStateActive &&
			response.CurrentVersionNumber != nil {
			if *response.CurrentVersionNumber != 1 {
				return ErrProvision
			}
			break
		}
		if time.Now().After(deadline) || ctx.Err() != nil {
			return ErrProvision
		}
		select {
		case <-ctx.Done():
			return ErrProvision
		case <-time.After(time.Second):
		}
	}
	version := int64(1)
	response, err := bundles.GetSecretBundle(ociclient.RequestContext(ctx), ocisecrets.GetSecretBundleRequest{SecretId: new(id), VersionNumber: &version})
	if err != nil || response.SecretId == nil || *response.SecretId != id || response.VersionNumber == nil || *response.VersionNumber != 1 {
		return ErrProvision
	}
	content, ok := response.SecretBundleContent.(ocisecrets.Base64SecretBundleContentDetails)
	if !ok {
		pointer, pointerOK := response.SecretBundleContent.(*ocisecrets.Base64SecretBundleContentDetails)
		if !pointerOK || pointer == nil {
			return ErrProvision
		}
		content = *pointer
	}
	if content.Content == nil {
		return ErrProvision
	}
	body, err := base64.StdEncoding.Strict().DecodeString(*content.Content)
	if err != nil || int64(len(body)) != file.MaxBytes {
		clear(body)
		return ErrProvision
	}
	defer clear(body)
	want, err := hex.DecodeString(file.SHA256)
	if err != nil {
		return ErrProvision
	}
	sum := sha256.Sum256(body)
	if subtle.ConstantTimeCompare(sum[:], want) != 1 {
		return ErrProvision
	}
	return nil
}

func saveJournal(ctx context.Context, directory string, state journal) error {
	wire, err := json.Marshal(state)
	if err != nil {
		return ErrProvision
	}
	temporary := filepath.Join(directory, journalTempName)
	if _, err := os.Lstat(temporary); err == nil {
		if err := ownedRegular(temporary, 0, 1<<20); err != nil {
			return ErrProvision
		}
		if err := os.Remove(temporary); err != nil {
			return ErrProvision
		}
	} else if !errors.Is(err, os.ErrNotExist) {
		return ErrProvision
	}
	if err := writeOnce(temporary, wire); err != nil {
		return ErrProvision
	}
	defer os.Remove(temporary)
	if err := GuardPublication(ctx); err != nil {
		return err
	}
	if err := os.Rename(temporary, filepath.Join(directory, journalName)); err != nil {
		return ErrProvision
	}
	if err := syncDirectory(directory); err != nil {
		return ErrProvision
	}
	return GuardPublication(ctx)
}

func validatePublication(directory string, record Record, publication Publication, journalWire []byte) error {
	if publication.SchemaVersion != 1 || publication.Target.Validate(record.Config.Region) != nil {
		return ErrProvision
	}
	metadata, err := readOwnedFile(filepath.Join(directory, metadataName), 1<<20)
	if err != nil || publication.MaterialSHA256 != digest(metadata) {
		return ErrProvision
	}
	var state journal
	if json.Unmarshal(journalWire, &state, json.RejectUnknownMembers(true)) != nil || state.SchemaVersion != 1 || state.Target != publication.Target || state.MaterialSHA256 != publication.MaterialSHA256 || len(state.Entries) != len(publication.References) {
		return ErrProvision
	}
	expected := 0
	for _, file := range record.Files {
		if file.Purpose != "owner-only" {
			expected++
		}
	}
	if len(state.Entries) != expected {
		return ErrProvision
	}
	for index, entry := range state.Entries {
		file, ok := findFile(record, entry.FileName)
		if !ok || file.Purpose == "owner-only" || entry.Name != secretName(record.Config, file) || !entry.Verified || entry.SentAt.IsZero() || !regionalResourceOCID(entry.SecretOCID, "vaultsecret", record.Config.Region) || index > 0 && state.Entries[index-1].FileName >= entry.FileName {
			return ErrProvision
		}
		if _, err := uuid.Parse(entry.RetryToken); err != nil {
			return ErrProvision
		}
		want := PublicReference{SecretName: entry.Name, Reference: bootstrap.SecretReference{Purpose: file.Purpose, Slot: file.Slot, SecretOCID: entry.SecretOCID, VersionNumber: 1, SHA256: file.SHA256, MaxBytes: file.MaxBytes, TargetFile: file.Name}}
		if publication.References[index] != want {
			return ErrProvision
		}
	}
	return nil
}

